"""Migrated Meridian CRM 4.2 ACCT_MASTER validation rules."""

from decimal import Decimal
from typing import Any


def _text(value: Any) -> str:
    """Return the legacy empty-string representation for absent values."""
    if value is None:
        return ""
    return str(value)


def _number(value: Any) -> Decimal:
    """Apply legacy numeric coercion: blank and missing values are zero."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image in legacy rule-file order."""
    del today  # Included for the fixed interface; unused by these rules.

    errors: list[dict] = []

    def add(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    if event in ("INSERT", "UPDATE"):
        # ACC-001
        if len(_text(record.get("ACCT_NM", ""))) < 2:
            add("E1001", "Account name too short")

        # ACC-002
        if _text(record.get("ACCT_TYP", "")) not in ("C", "P", "R", "X"):
            add("E1002", "Invalid account type")

        # ACC-003
        if _number(record.get("ANN_REV", "")) < Decimal("0"):
            add("E1003", "Annual revenue negative")

    if event == "UPDATE":
        old_record = old if old is not None else {}

        # ACC-004
        if (
            _text(old_record.get("CRED_HOLD", "")) == "Y"
            and _text(record.get("CRED_HOLD", "")) == "N"
            and _number(record.get("CRED_LIMIT", "")) <= Decimal("0")
        ):
            add("E1004", "Cannot release credit hold with zero credit limit")

    if event in ("INSERT", "UPDATE"):
        # ACC-005
        if len(_text(record.get("REGION_CD", ""))) != 3:
            add("E1005", "Region code must be 3 chars", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
